const $ = id => document.getElementById(id);
const modal = $('modal');
const panel = $('panel');

const draftKey = 'agrodetail-cotacao-precos-v3';
const draftLifetime = 24 * 60 * 60 * 1000;
let cart = {};
let preferences = {payment:'A combinar', notes:''};
let expiresAt = 0;
function loadDraft() {
  cart = {};
  preferences = {payment:'A combinar', notes:''};
  expiresAt = 0;
  try {
    localStorage.removeItem('agrodetail-cotacao-v1');
    localStorage.removeItem('agrodetail-cotacao-v2');
    localStorage.removeItem('agrodetail-atendimento-v1');
    const saved = JSON.parse(localStorage.getItem(draftKey));
    if (!saved || !Number.isFinite(saved.expiresAt) || saved.expiresAt <= Date.now()) {
      localStorage.removeItem(draftKey);
      return;
    }
    expiresAt = saved.expiresAt;
    for (const {id} of products) {
      if (Number.isInteger(saved.items?.[id]) && saved.items[id] > 0 && saved.items[id] <= 999) cart[id] = saved.items[id];
    }
    if (typeof saved.preferences?.payment === 'string') preferences.payment = saved.preferences.payment;
    if (typeof saved.preferences?.notes === 'string') preferences.notes = saved.preferences.notes;
  } catch {}
}
function refreshDraft() {
  loadDraft();

}
function saveDraft() {
  if (!Object.keys(cart).length) {
    expiresAt = 0;
    preferences = {payment:'A combinar', notes:''};
  } else if (!expiresAt) {
    expiresAt = Date.now() + draftLifetime;
  }
  try {
    if (expiresAt) localStorage.setItem(draftKey, JSON.stringify({items:cart,preferences,expiresAt}));
    else localStorage.removeItem(draftKey);
  } catch {}
}
function syncCart() {
  saveDraft();

}
function change(id, amount) {
  refreshDraft();
  cart[id] = Math.min(999, Math.max(0,(cart[id] || 0) + amount));
  if (!cart[id]) delete cart[id];
  syncCart();
}
function normalize(value) {
  return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
}
function photo({x,y,w,h,image,name}) {
  if (image) return '<img class="product-photo" src="'+image+'" alt="'+name+'" loading="lazy">';
  return '<span class="photo" aria-hidden="true" style="--w:'+w+'px;--h:'+h+'px;--pos:-'+x+'px -'+y+'px"></span>';
}

function productUrl(product) {
  return '/?produto=' + encodeURIComponent(product.id);
}
const money = cents => new Intl.NumberFormat('pt-BR', {style:'currency',currency:'BRL'}).format(cents / 100);
const hasPrice = product => Number.isInteger(product.priceCents) && product.priceCents > 0;
function priceLabel(product) {
  return hasPrice(product) ? money(product.priceCents) + ' / ' + product.priceUnit : 'Preço sob consulta';
}
function quoteTotal(items) {
  const priced = items.filter(hasPrice);
  const total = priced.reduce((sum, product) => sum + product.priceCents * cart[product.id], 0);
  if (!priced.length) return 'Total sob consulta';
  return (priced.length === items.length ? 'Total dos produtos: ' : 'Subtotal dos produtos com preço: ') + money(total) + (priced.length < items.length ? '. Há itens sob consulta.' : '');
}
function showProduct(code) {
  const product = products.find(item => item.id === code);
  $('hero').hidden = true;
  $('catalogo').hidden = true;
  const page = $('productPage');
  page.hidden = false;
  const back = '<a class="official-link" href="/#catalogo">Voltar ao catálogo</a>';
  if (!product) {
    page.innerHTML = back + '<h1>Produto não encontrado</h1>';
    return;
  }
  document.title = product.name + ' | AgroDetail | Autolimpe';
  page.innerHTML = back + '<div class="detail-grid"><div class="visual">' + photo(product) +
    '</div><article class="detail-info"><span class="code">' + product.id + '</span><h1>' + product.name +
    '</h1><p class="price">'+priceLabel(product)+'</p><dl><div><dt>Código</dt><dd>' + product.id +
    '</dd></div><div><dt>Categoria</dt><dd>' + product.category +
    '</dd></div><div><dt>Marca</dt><dd>' + product.brand +
    '</dd></div><div><dt>Embalagens</dt><dd>'+escapeHtml(product.packaging)+'</dd></div><div><dt>Diluição</dt><dd>'+escapeHtml(product.dilution)+'</dd></div></dl><p class="description">'+escapeHtml(product.description)+'</p><p class="muted">Consulte disponibilidade e condições para compra ou revenda.</p>' +
    '<form id="productPurchase" class="purchase"><label>Quantidade de ' + (product.priceUnit === 'caixa' ? 'caixas' : 'unidades') + '<input id="productQuantity" type="number" min="1" max="999" value="1" required></label>' +
    '<button type="submit">Adicionar à cotação</button></form><p id="productNotice" role="status"></p></article></div>';
  $('productPurchase').addEventListener('submit', event => {
    event.preventDefault();
    requestAdd(product.id, $('productQuantity').valueAsNumber);
  });
}
document.addEventListener('error', event => {
  if (!event.target.matches?.('.product-photo')) return;
  const placeholder = document.createElement('span');
  placeholder.className = 'photo-placeholder';
  placeholder.textContent = 'Foto indisponível';
  event.target.replaceWith(placeholder);
}, true);
function render() {
  const query = normalize($('search').value);
  const visible = products.filter(p => normalize(p.name+' '+p.id+' '+p.brand).includes(query)
    && (!$('category').value || p.category === $('category').value)
    && (!$('brand').value || p.brand === $('brand').value));
  $('count').textContent = visible.length + (visible.length === 1 ? ' produto' : ' produtos');
  $('grid').innerHTML = visible.map(p => '<article class="product"><a class="visual product-link" href="'+productUrl(p)+'" aria-label="Ver detalhes de '+p.name+' '+p.id+'">'+photo(p)+'</a><div class="body"><span class="code">'+p.category+'</span><h3><a class="product-link" href="'+productUrl(p)+'">'+p.name+'</a></h3><p class="muted">Marca: '+p.brand+'</p><p class="price">'+priceLabel(p)+'</p><p class="muted">'+escapeHtml(p.packaging)+'</p><button data-add="'+p.id+'" type="button">Adicionar à cotação</button></div></article>').join('') || '<p class="empty">Nenhum produto encontrado com esses filtros.</p>';
}
function open(title, content) {
  $('dialogTitle').textContent = title;
  panel.innerHTML = content;
  if (!modal.open) modal.showModal();
}
function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
}
function requestAdd(id, quantity) {
  if (!products.some(product => product.id === id) || !Number.isInteger(quantity) || quantity < 1 || quantity > 999) return;
  showContact('adicionar', {id, quantity});
}
function showCart() {
  refreshDraft();
  const items = products.filter(product => cart[product.id]);
  const lines = items.map(product => '<div class="quote-line"><a href="'+productUrl(product)+'" class="quote-photo">'+photo(product)+'</a><div><a class="product-link" href="'+productUrl(product)+'"><strong>'+product.name+'</strong></a><p class="muted">'+product.id+' · '+product.brand+'</p><p>'+escapeHtml(product.packaging)+'</p><span>'+priceLabel(product)+(hasPrice(product) ? ' · Subtotal: '+money(product.priceCents * cart[product.id]) : '')+'</span><div class="quantity"><button data-minus="'+product.id+'" aria-label="Diminuir '+product.id+'">−</button><span>'+cart[product.id]+'</span><button data-plus="'+product.id+'" aria-label="Aumentar '+product.id+'">+</button><button class="secondary" data-remove="'+product.id+'">Excluir</button></div></div></div>').join('');
  open('Minha cotação', items.length ? lines+
    '<p><strong>'+quoteTotal(items)+'</strong></p><p class="muted">Valores da Tabela Geral por embalagem indicada. Frete a combinar. Cada quantidade corresponde a uma caixa ou unidade descrita.</p><label class="quote-field">Condição de pagamento<select id="payment"><option>A combinar</option><option>Solicitar condição à vista</option><option>Solicitar condição parcelada</option></select></label>'+
    '<label class="quote-field">Observações<textarea id="notes" rows="3" maxlength="2000" placeholder="Conte sobre a aplicação, a entrega ou o interesse em revenda"></textarea></label>'+
    '<div class="actions"><button data-flow="cotacao">Enviar minha cotação</button><button class="secondary" data-flow="vendedor">Falar com um vendedor</button><button class="secondary" data-browse>Continuar explorando</button></div>' :
    '<p>Selecione os produtos para montar sua cotação.</p><div class="actions"><button data-browse>Explorar catálogo</button><button class="secondary" data-flow="vendedor">Falar com um vendedor</button></div>');
  if (items.length) {
    $('payment').value = preferences.payment;
    $('notes').value = preferences.notes;
    for (const id of ['payment','notes']) $(id).addEventListener('input', () => {
      preferences = {payment:$('payment').value, notes:$('notes').value};
      saveDraft();
    });
  }
}
const states = 'AC AL AP AM BA CE DF ES GO MA MT MS MG PA PB PR PE PI RJ RN RS RO RR SC SP SE TO'.split(' ');
function showContact(flow, pending) {
  refreshDraft();
  const current = products.find(product => product.id === new URLSearchParams(location.search).get('produto'));
  open(flow === 'adicionar' || flow === 'cotacao' ? 'Enviar minha cotação' : 'Falar com um vendedor',
    '<p class="notice">Prévia do catálogo. O envio ao CRM está em configuração. Use dados fictícios para testar.</p>'+
    '<form id="contactForm"><div class="fields"><label>Nome<input name="nome" required maxlength="120" autocomplete="name"></label><label>WhatsApp<input name="telefone" type="tel" required maxlength="25" autocomplete="tel" placeholder="(00) 00000-0000"></label>'+
    '<label>Cidade<input name="cidade" required maxlength="100" autocomplete="address-level2"></label><label>UF<select name="estado" required><option value="">Selecione</option>'+states.map(state=>'<option>'+state+'</option>').join('')+'</select></label>'+
    '<label>Empresa / CNPJ (opcional)<input name="cnpj" maxlength="40"></label><label>E-mail (opcional)<input name="email" type="email" maxlength="160" autocomplete="email"></label>'+
    '<label>Produto de interesse (opcional)<input name="interesse" maxlength="200" placeholder="Nome ou código do produto"></label></div>'+
    '<div class="actions"><button type="submit">'+(flow === 'adicionar' ? 'Continuar para minha cotação' : flow === 'vendedor' ? 'Solicitar atendimento' : 'Enviar cotação')+'</button></div></form>');
  const form = $('contactForm');

  form.elements.interesse.value = pending ? products.find(product=>product.id===pending.id).name : current?.name || '';
  form.addEventListener('submit', event => {
    event.preventDefault();
    const phone = form.elements.telefone;
    phone.setCustomValidity(/^\d{10,13}$/.test(phone.value.replace(/\D/g,'')) ? '' : 'Informe o WhatsApp com DDD.');
    if (!form.reportValidity()) return;
    const contact = Object.fromEntries(new FormData(form));
    if (pending) {
      change(pending.id,pending.quantity);
      $('status').textContent = 'Dados preenchidos. Produto adicionado à sua cotação.';
      showCart();
      return;
    }
    const payload = {
      origem:'catalogo-digital-agrodetail', tipo:flow, ...contact,
      itens:products.filter(product=>cart[product.id]).map(product=>({codigo:product.sku || product.id,nome:product.name,embalagem:product.packaging,quantidade:cart[product.id],preco_centavos:product.priceCents,subtotal_centavos:hasPrice(product)?product.priceCents*cart[product.id]:null})),
      condicao_pagamento:preferences.payment, observacoes:preferences.notes
    };
    const requestId = crypto.randomUUID();
    cart = {};
    syncCart();
    open('Prévia da solicitação','<p class="notice">Solicitação preparada para '+(flow==='cotacao'?'cotação':'atendimento com vendedor')+'. O CRM ainda precisa ser conectado para realizar o envio.</p><p><strong>'+escapeHtml(payload.nome)+'</strong> · '+escapeHtml(payload.cidade)+' / '+escapeHtml(payload.estado)+'</p><p>'+payload.itens.length+' tipos de produto selecionados.</p><p>Simulação '+requestId+'. Seleção encerrada. Uma nova solicitação começa com os dados em branco.</p><button data-show-quote>Voltar à minha cotação</button>');
  });
  form.elements.telefone.addEventListener('input',()=>form.elements.telefone.setCustomValidity(''));
}
for (const id of ['search','category','brand']) $(id).addEventListener('input',render);
$('cartButton').onclick = showCart;
$('close').onclick = () => modal.close();
document.addEventListener('click', event => {
  const button = event.target.closest('button');
  if (!button) return;
  const {add,minus,plus,remove,browse,flow,showQuote} = button.dataset;
  if (add) requestAdd(add,1);
  if (minus || plus || remove) {
    if (remove) delete cart[remove];
    else change(minus || plus,minus ? -1 : 1);
    syncCart();
    showCart();
  }
  if (flow) showContact(flow);
  if (showQuote !== undefined) showCart();
  if (browse !== undefined) {
    modal.close();
    if (location.search) location.href='/#catalogo';
    else $('catalogo').scrollIntoView({behavior:'smooth'});
  }
});
refreshDraft();
window.addEventListener('focus', refreshDraft);
window.addEventListener('storage', event => { if (event.key === draftKey) refreshDraft(); });
const code = new URLSearchParams(location.search).get('produto');
if (code === null) render();
else showProduct(code);
syncCart();
